HTML_TEXT = '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">\n<meta name="theme-color" content="#F7F8FA">\n<title>全能助手</title>\n<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 24 24\'%3E%3Crect width=\'24\' height=\'24\' rx=\'5\' fill=\'%230F766E\'/%3E%3Cpath d=\'M7 8.5h10M7 12h6M7 15.5h8\' stroke=\'white\' stroke-width=\'1.8\' stroke-linecap=\'round\'/%3E%3C/svg%3E">\n<link rel="manifest" href="/manifest.webmanifest">\n<link rel="apple-touch-icon" href="/icons/apple-touch-icon.png">\n<meta name="mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="全能助手">\n<style>\n/* ============ 基础 ============ */\n* { margin: 0; padding: 0; box-sizing: border-box; }\n:root {\n  --bg: #F7F8FA;\n  --panel: #FFFFFF;\n  --ink: #1A1D21;\n  --ink-2: #5F6770;\n  --ink-3: #9AA1A9;\n  --line: #E3E6EA;\n  --accent: #0F766E;\n  --accent-soft: #E8F4F2;\n  --danger: #C0392B;\n}\nhtml, body { height: 100%; }\nbody {\n  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", -apple-system, "Segoe UI", sans-serif;\n  background: var(--bg);\n  color: var(--ink);\n  -webkit-font-smoothing: antialiased;\n}\nbutton { font-family: inherit; cursor: pointer; }\nbutton:focus-visible, textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n\n/* ============ 整体布局 ============ */\n.app {\n  height: 100dvh;\n  max-width: 820px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  background: var(--panel);\n  box-shadow: 0 0 0 1px var(--line);\n  position: relative;\n  overflow: hidden;\n}\n\n/* ============ 顶栏 ============ */\n.header {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: calc(10px + env(safe-area-inset-top)) 12px 10px;\n  border-bottom: 1px solid var(--line);\n  background: var(--panel);\n  z-index: 5;\n}\n.brand { display: flex; align-items: center; gap: 8px; min-width: 0; }\n.brand-mark {\n  width: 30px; height: 30px; border-radius: 8px;\n  background: var(--accent); color: #fff;\n  display: flex; align-items: center; justify-content: center;\n  flex: 0 0 auto;\n  transition: background .2s;\n}\n.brand-name { font-size: 16px; font-weight: 700; letter-spacing: .5px; white-space: nowrap; }\n\n/* 角色 tab（横向滚动） */\n.tabs {\n  flex: 1 1 auto;\n  min-width: 0;\n  display: flex;\n  gap: 6px;\n  overflow-x: auto;\n  scrollbar-width: none;\n  -webkit-overflow-scrolling: touch;\n}\n.tabs::-webkit-scrollbar { display: none; }\n.tab {\n  border: 1px solid var(--line); background: var(--bg); border-radius: 999px;\n  min-height: 44px; padding: 8px 14px; font-size: 13px; color: var(--ink-2);\n  display: inline-flex; align-items: center; gap: 5px;\n  white-space: nowrap; flex: 0 0 auto;\n  transition: background .15s, color .15s;\n}\n.tab .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--ink-3); flex: 0 0 auto; }\n.tab.active { background: var(--panel); color: var(--accent); font-weight: 600; box-shadow: 0 1px 3px rgba(0,0,0,.1); }\n.tab.active .dot { background: var(--accent); }\n.icon-btn {\n  border: 1px solid var(--line); background: var(--panel); border-radius: 10px;\n  width: 44px; height: 44px; display: flex; align-items: center; justify-content: center;\n  color: var(--ink-2); flex: 0 0 auto;\n  transition: background .15s, color .15s;\n}\n.icon-btn svg { width: 17px; height: 17px; }\n.icon-btn:hover { background: var(--bg); color: var(--ink); }\n.icon-btn.on { background: var(--danger); border-color: var(--danger); color: #fff; }\n\n/* ============ 消息区 ============ */\n.main {\n  flex: 1 1 auto;\n  overflow-y: auto;\n  -webkit-overflow-scrolling: touch;\n  padding: 16px 14px 8px;\n  scroll-behavior: auto;\n}\n.msg { display: flex; margin-bottom: 14px; }\n.msg.user { justify-content: flex-end; }\n.msg .bubble {\n  max-width: 82%;\n  padding: 10px 13px;\n  border-radius: 14px;\n  font-size: 15px;\n  line-height: 1.65;\n  word-break: break-word;\n  white-space: pre-wrap;\n}\n.msg.user .bubble {\n  background: var(--accent); color: #fff;\n  border-bottom-right-radius: 4px;\n}\n.msg.ai { justify-content: flex-start; }\n.msg.ai .bubble {\n  background: var(--bg);\n  border: 1px solid var(--line);\n  border-bottom-left-radius: 4px;\n  white-space: normal;\n}\n.msg.ai .bubble p { margin: 0 0 8px; }\n.msg.ai .bubble p:last-child { margin-bottom: 0; }\n.msg.ai .bubble strong { font-weight: 700; }\n.msg.ai .bubble ul, .msg.ai .bubble ol { margin: 4px 0 8px; padding-left: 20px; }\n.msg.ai .bubble li { margin-bottom: 3px; }\n.msg.ai .bubble code {\n  font-family: Consolas, "Courier New", monospace;\n  background: rgba(0,0,0,.06); border-radius: 4px; padding: 1px 4px;\n  font-size: 13px;\n}\n.msg.ai .bubble pre {\n  background: #1F2428; color: #E8ECEF; border-radius: 8px;\n  padding: 10px 12px; overflow-x: auto; margin: 8px 0;\n  font-size: 13px; line-height: 1.5;\n}\n.msg.ai .bubble pre code { background: none; color: inherit; padding: 0; }\n.msg.ai .bubble h1, .msg.ai .bubble h2, .msg.ai .bubble h3 { font-size: 15px; margin: 10px 0 6px; }\n.msg.ai .bubble hr { border: 0; border-top: 1px solid var(--line); margin: 10px 0; }\n.msg.ai.streaming .bubble { border-color: var(--accent); }\n\n/* ============ 欢迎屏 ============ */\n.welcome { padding: 18px 4px 4px; }\n.welcome h2 { font-size: 20px; margin-bottom: 6px; }\n.welcome .sub { color: var(--ink-2); font-size: 14px; margin-bottom: 18px; }\n.cards { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 20px; }\n.card {\n  border: 1px solid var(--line); border-radius: 12px; padding: 13px;\n  cursor: pointer; text-align: left; background: var(--panel);\n  transition: border-color .15s, background .15s;\n}\n.card:hover { border-color: var(--accent); background: var(--accent-soft); }\n.card .card-tag {\n  display: inline-flex; align-items: center; gap: 5px;\n  font-size: 14px; font-weight: 700; margin-bottom: 8px;\n  color: var(--accent);\n}\n.card .card-tag svg { width: 13px; height: 13px; }\n.card .card-name { font-size: 14px; font-weight: 600; margin-bottom: 4px; }\n.card .card-desc { font-size: 14px; color: var(--ink-2); line-height: 1.5; }\n.chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; }\n.chip {\n  border: 1px solid var(--line); background: var(--panel); border-radius: 999px;\n  min-height: 44px; padding: 8px 15px; font-size: 13px; color: var(--ink-2);\n  transition: border-color .15s, color .15s;\n}\n.chip:hover { border-color: var(--accent); color: var(--accent); }\n.hint { font-size: 13px; color: var(--ink-3); line-height: 1.6; }\n\n/* ============ 输入区 ============ */\n.input-bar {\n  flex: 0 0 auto;\n  border-top: 1px solid var(--line);\n  padding: 10px 12px calc(10px + env(safe-area-inset-bottom));\n  background: var(--panel);\n  display: flex;\n  align-items: flex-end;\n  gap: 8px;\n}\n.mic-btn {\n  border: 1px solid var(--line); background: var(--bg); border-radius: 12px;\n  width: 44px; height: 44px; flex: 0 0 auto;\n  display: flex; align-items: center; justify-content: center;\n  color: var(--ink-2);\n  transition: background .15s, color .15s, border-color .15s;\n}\n.mic-btn svg { width: 18px; height: 18px; }\n.mic-btn.on { background: var(--danger); border-color: var(--danger); color: #fff; }\n.input-box {\n  flex: 1 1 auto;\n  border: 1px solid var(--line); border-radius: 12px;\n  background: var(--bg);\n  padding: 10px 12px;\n  display: flex;\n  align-items: flex-end;\n  gap: 6px;\n  transition: border-color .15s;\n}\n.input-box:focus-within { border-color: var(--accent); background: var(--panel); }\ntextarea {\n  flex: 1 1 auto; border: 0; background: transparent; resize: none;\n  font-family: inherit; font-size: 16px; line-height: 1.5; color: var(--ink);\n  max-height: 120px; min-height: 24px;\n}\ntextarea:focus { outline: 0; }\n.send-btn {\n  border: 0; border-radius: 12px;\n  width: 44px; height: 44px; flex: 0 0 auto;\n  background: var(--accent); color: #fff;\n  display: flex; align-items: center; justify-content: center;\n  transition: background .2s, opacity .2s;\n}\n.send-btn svg { width: 18px; height: 18px; }\n.send-btn:disabled { opacity: .45; cursor: not-allowed; }\n\n/* ============ 提示条 ============ */\n.banner {\n  flex: 0 0 auto;\n  background: #FDF3F2; color: var(--danger);\n  font-size: 13px; line-height: 1.5;\n  padding: 8px 14px;\n  border-bottom: 1px solid #F3D9D6;\n  display: none;\n}\n.banner.show { display: block; }\n.banner .banner-act { color: var(--danger); text-decoration: underline; font-weight: 600; background: none; border: 0; }\n\n/* ============ 打字指示 ============ */\n.typing .bubble { display: flex; gap: 5px; align-items: center; padding: 14px 16px; }\n.typing .dot {\n  width: 7px; height: 7px; border-radius: 50%; background: var(--ink-3);\n  animation: blink 1.2s infinite;\n}\n.typing .dot:nth-child(2) { animation-delay: .2s; }\n.typing .dot:nth-child(3) { animation-delay: .4s; }\n@keyframes blink { 0%, 80%, 100% { opacity: .25; } 40% { opacity: 1; } }\n\n/* ============ 弹窗 ============ */\n.overlay {\n  position: fixed; inset: 0; background: rgba(15,18,20,.45);\n  display: none; align-items: flex-end; justify-content: center; z-index: 20;\n}\n.overlay.show { display: flex; }\n.sheet {\n  background: var(--panel); width: 100%; max-width: 520px;\n  border-radius: 16px 16px 0 0;\n  padding: 18px 18px calc(18px + env(safe-area-inset-bottom));\n  max-height: 78dvh; overflow-y: auto;\n}\n.sheet h3 { font-size: 16px; margin-bottom: 14px; }\n.sheet h4 { font-size: 14px; margin: 18px 0 8px; }\n.sheet .row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-top: 1px solid var(--line); font-size: 14px; }\n.sheet .row:first-of-type { border-top: 0; }\n.sheet .row .k { color: var(--ink-2); }\n.sheet .row .v { font-weight: 600; text-align: right; max-width: 60%; }\n.sheet .row .v.ok { color: var(--accent); }\n.sheet .row .v.bad { color: var(--danger); }\n.sheet .desc { font-size: 13.5px; color: var(--ink-2); line-height: 1.6; margin: 10px 0 4px; }\n.switch-row { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-top: 1px solid var(--line); }\n.switch-row .k { font-size: 14px; color: var(--ink-2); }\n.switch {\n  position: relative; width: 48px; height: 28px; flex: 0 0 auto;\n  border: 1px solid var(--line); border-radius: 999px; background: var(--bg);\n  transition: background .15s, border-color .15s;\n}\n.switch::after {\n  content: ""; position: absolute; top: 2px; left: 2px;\n  width: 22px; height: 22px; border-radius: 50%; background: #fff;\n  box-shadow: 0 1px 2px rgba(0,0,0,.2);\n  transition: left .15s;\n}\n.switch.on { background: var(--accent); border-color: var(--accent); }\n.switch.on::after { left: 22px; }\n.mem-add { display: flex; gap: 8px; margin: 8px 0; }\n.mem-add input {\n  flex: 1 1 auto; border: 1px solid var(--line); border-radius: 10px;\n  padding: 10px 12px; font-size: 14px; font-family: inherit; background: var(--bg);\n}\n.mem-add input:focus { outline: 0; border-color: var(--accent); background: var(--panel); }\n.mem-add button {\n  border: 0; border-radius: 10px; background: var(--accent); color: #fff;\n  padding: 0 16px; font-size: 14px; font-weight: 600; flex: 0 0 auto;\n}\n.mem-item {\n  display: flex; justify-content: space-between; align-items: center; gap: 10px;\n  padding: 9px 0; border-top: 1px solid var(--line); font-size: 14px;\n}\n.mem-item:first-of-type { border-top: 0; }\n.mem-item .t { color: var(--ink); line-height: 1.5; }\n.mem-item button {\n  border: 1px solid #F3D9D6; background: #FDF3F2; color: var(--danger);\n  border-radius: 8px; padding: 6px 12px; font-size: 12.5px; flex: 0 0 auto;\n}\n.danger-btn {\n  margin-top: 14px; width: 100%;\n  border: 1px solid #F3D9D6; background: #FDF3F2; color: var(--danger);\n  border-radius: 10px; padding: 11px; font-size: 14px; font-weight: 600;\n}\n.danger-btn:hover { background: #FAE6E3; }\n\n/* ============ 桌面适配 ============ */\n@media (min-width: 900px) {\n  .app { border-radius: 0; height: 100dvh; }\n  .msg .bubble { max-width: 70%; }\n}\n@media (max-width: 480px) {\n  .cards { grid-template-columns: 1fr; }\n  .brand-name { font-size: 15px; }\n  .tab { padding: 6px 11px; font-size: 13px; min-height: 44px; }\n}\n</style>\n</head>\n<body>\n<div class="app" id="app">\n\n  <div class="banner" id="banner">\n    <span id="bannerText"></span>\n    <button class="banner-act" id="bannerAct" type="button"></button>\n  </div>\n\n  <header class="header">\n    <div class="brand">\n      <div class="brand-mark" id="brandMark" aria-hidden="true">\n        <svg viewBox="0 0 24 24" fill="none" width="16" height="16"><path d="M7 8.5h10M7 12h6M7 15.5h8" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/></svg>\n      </div>\n      <span class="brand-name">全能助手</span>\n    </div>\n    <div class="tabs" id="tabs" role="tablist" aria-label="模式切换"></div>\n    <button class="icon-btn" id="btnSpeak" type="button" aria-label="朗读最后一条回复" title="朗读回复">\n      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M11 5 6 9H2v6h4l5 4V5z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/></svg>\n    </button>\n    <button class="icon-btn" id="btnSettings" type="button" aria-label="设置" title="设置">\n      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.6-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.9.3h.1a1.7 1.7 0 0 0 1-1.6V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.6h.1a1.7 1.7 0 0 0 1.9-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.9v.1a1.7 1.7 0 0 0 1.6 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.6 1z"/></svg>\n    </button>\n  </header>\n\n  <main class="main" id="main">\n    <section class="welcome" id="welcome">\n      <h2>你好，我是全能助手</h2>\n      <p class="sub">工作和情感，一个对话搞定。切模式，换人格。</p>\n      <div class="cards" id="cards"></div>\n      <div class="chips" id="chips">\n        <button class="chip" type="button">帮我写国创商业计划书大纲</button>\n        <button class="chip" type="button">这段代码报错怎么排查</button>\n        <button class="chip" type="button">把这段文字去AI化降重</button>\n        <button class="chip" type="button">最近很焦虑，内耗严重</button>\n        <button class="chip" type="button">帮我分析这段聊天记录</button>\n        <button class="chip" type="button">做一份周报模板</button>\n      </div>\n      <p class="hint">发送即表示使用本机配置的 API 服务。聊天记录和记忆只保存在这台浏览器里。</p>\n    </section>\n    <div id="messages"></div>\n  </main>\n\n  <footer class="input-bar">\n    <button class="mic-btn" id="btnMic" type="button" aria-label="语音输入" title="语音输入" style="display:none;">\n      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8"/></svg>\n    </button>\n    <div class="input-box">\n      <textarea id="input" rows="1" placeholder="问点什么…（Enter 发送，Shift+Enter 换行）" aria-label="输入消息"></textarea>\n    </div>\n    <button class="send-btn" id="send" type="button" aria-label="发送" title="发送">\n      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 2 11 13M22 2l-7 20-4-9-9-4 20-7z"/></svg>\n    </button>\n  </footer>\n\n  <div class="overlay" id="overlay">\n    <div class="sheet" role="dialog" aria-label="设置">\n      <h3>设置</h3>\n      <div class="row"><span class="k">后端状态</span><span class="v" id="stReady">检测中…</span></div>\n      <div class="row"><span class="k">服务商</span><span class="v" id="stProvider">—</span></div>\n      <div class="row"><span class="k">模型</span><span class="v" id="stModel">—</span></div>\n      <div class="row"><span class="k">可用服务商</span><span class="v" id="stProviders">—</span></div>\n      <div class="row"><span class="k">模式路由</span><span class="v" id="stRouting">—</span></div>\n      <div class="row"><span class="k">配置位置</span><span class="v" id="stConfig">—</span></div>\n\n      <h4>直连云端模式（APP 独立用）</h4>\n      <p class="desc">填入 Key 后，手机不依赖电脑后端、直接调用云端 API——把网页"添加到主屏幕"后就是独立 APP。不填则照常用局域网后端。Key 只存这台浏览器。</p>\n      <div style="display:flex;flex-direction:column;gap:8px;margin:10px 0;">\n        <select id="dcProvider" style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;font-family:inherit;background:var(--bg);color:var(--ink);">\n          <option value="deepseek">DeepSeek</option>\n          <option value="zhipu">智谱 GLM（glm-4-flash 免费）</option>\n          <option value="volc">豆包（火山方舟）</option>\n          <option value="qwen">通义（阿里百炼，备用）</option>\n          <option value="sensenova">商汤日日新（仅云函数后端）</option>\n          <option value="minimax">MiniMax（新用户送额度）</option>\n          <option value="stepfun">阶跃星辰（免费模型）</option>\n          <option value="qianfan">百度千帆（新用户送额度）</option>\n          <option value="lingyi">零一万物</option>\n          <option value="custom">自定义（中转站等）</option>\n        </select>\n        <input id="dcKey" type="password" placeholder="API Key（如 sk-...）" maxlength="200" style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;font-family:inherit;background:var(--bg);">\n        <input id="dcUrl" type="text" placeholder="base_url（留空=DeepSeek）" maxlength="200" style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;font-family:inherit;background:var(--bg);">\n        <input id="dcModel" type="text" placeholder="model（留空=deepseek-chat）" maxlength="80" style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:14px;font-family:inherit;background:var(--bg);">\n        <textarea id="dcPrompts" rows="3" placeholder=\'{"work":"...","emotion":"..."} 可选，覆盖直连人格；留空用内置\' style="border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:13px;font-family:inherit;background:var(--bg);resize:vertical;"></textarea>\n        <button id="dcSave" type="button" style="border:0;border-radius:10px;background:var(--accent);color:#fff;padding:11px;font-size:14px;font-weight:600;">保存直连配置</button>\n        <button id="dcClear" type="button" style="border:1px solid #F3D9D6;background:#FDF3F2;color:var(--danger);border-radius:10px;padding:10px;font-size:14px;">关闭直连（回到局域网后端）</button>\n      </div>\n      <div id="dcStatus" class="desc"></div>\n\n      <h4>朗读回复</h4>\n      <div class="switch-row">\n        <span class="k">回复完成后自动朗读（本地语音）</span>\n        <button class="switch" id="swSpeak" type="button" role="switch" aria-checked="false"></button>\n      </div>\n\n      <h4>记住的关键事实（轻量记忆）</h4>\n      <p class="desc">告诉助手关于你的事，它会在每次对话时带上这些信息，比如"我在三亚读飞机电子设备维修"。仅存本浏览器。</p>\n      <div class="mem-add">\n        <input id="memInput" type="text" placeholder="例如：我在读飞机电子设备维修专业" maxlength="120">\n        <button id="memAdd" type="button">添加</button>\n      </div>\n      <div id="memList"></div>\n\n      <p class="desc" style="margin-top:12px">API Key 填写在电脑上同目录的 <b>config.json</b> 里，改完重启 <b>server.py</b> 生效。多服务商与模式路由见 config.example.json。</p>\n      <button class="danger-btn" id="btnClear" type="button">清空当前会话记录</button>\n    </div>\n  </div>\n\n<!-- ====== JS ====== -->\n<script>\n(function () {\n  "use strict";\n\n  var DEFAULT_ROLES = [\n    { id: "work", name: "工作", color: "#0F766E" },\n    { id: "emotion", name: "情感", color: "#B45309" }\n  ];\n  var MEM_KEY = "qnz_memory";\n  var SPEAK_KEY = "qnz_speak";\n\n  var state = {\n    mode: "work",\n    busy: false,\n    roles: DEFAULT_ROLES.slice(),\n    histories: {}\n  };\n\n  /* ---------- 存储 ---------- */\n  function histKey(mode) { return "qnz_hist_" + mode; }\n  function loadHist(mode) {\n    try {\n      var raw = localStorage.getItem(histKey(mode));\n      var arr = raw ? JSON.parse(raw) : [];\n      return Array.isArray(arr) ? arr.slice(-100) : [];\n    } catch (e) { return []; }\n  }\n  function saveHist(mode) {\n    try {\n      localStorage.setItem(histKey(mode), JSON.stringify((state.histories[mode] || []).slice(-100)));\n    } catch (e) { /* 存储满时静默 */ }\n  }\n  function loadMem() {\n    try {\n      var a = JSON.parse(localStorage.getItem(MEM_KEY) || "[]");\n      return Array.isArray(a) ? a : [];\n    } catch (e) { return []; }\n  }\n  function saveMem(arr) {\n    try { localStorage.setItem(MEM_KEY, JSON.stringify(arr.slice(-50))); } catch (e) {}\n  }\n  function loadSpeak() { return localStorage.getItem(SPEAK_KEY) === "1"; }\n  function saveSpeak(on) {\n    try { localStorage.setItem(SPEAK_KEY, on ? "1" : "0"); } catch (e) {}\n  }\n\n  var el = {\n    main: document.getElementById("main"),\n    messages: document.getElementById("messages"),\n    welcome: document.getElementById("welcome"),\n    input: document.getElementById("input"),\n    send: document.getElementById("send"),\n    banner: document.getElementById("banner"),\n    bannerText: document.getElementById("bannerText"),\n    bannerAct: document.getElementById("bannerAct"),\n    tabs: document.getElementById("tabs"),\n    cards: document.getElementById("cards"),\n    brandMark: document.getElementById("brandMark"),\n    mic: document.getElementById("btnMic"),\n    speakBtn: document.getElementById("btnSpeak"),\n    overlay: document.getElementById("overlay"),\n    stReady: document.getElementById("stReady"),\n    stProvider: document.getElementById("stProvider"),\n    stModel: document.getElementById("stModel"),\n    swSpeak: document.getElementById("swSpeak"),\n    memInput: document.getElementById("memInput"),\n    memAdd: document.getElementById("memAdd"),\n    memList: document.getElementById("memList"),\n    stProviders: document.getElementById("stProviders"),\n    stRouting: document.getElementById("stRouting"),\n    stConfig: document.getElementById("stConfig"),\n    dcKey: document.getElementById("dcKey"),\n    dcProvider: document.getElementById("dcProvider"),\n    dcUrl: document.getElementById("dcUrl"),\n    dcModel: document.getElementById("dcModel"),\n    dcPrompts: document.getElementById("dcPrompts"),\n    dcSave: document.getElementById("dcSave"),\n    dcClear: document.getElementById("dcClear"),\n    dcStatus: document.getElementById("dcStatus")\n  };\n\n  /* ---------- 基础工具 ---------- */\n  function esc(s) {\n    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")\n      .replace(/"/g, "&quot;").replace(/\'/g, "&#39;");\n  }\n  // 极简 Markdown：先转义防注入，再还原少量标记\n  function md(src) {\n    var blocks = [];\n    var rest = String(src);\n    var re = /```([\\s\\S]*?)```/g, m;\n    while ((m = re.exec(rest)) !== null) {\n      blocks.push({ start: m.index, end: re.lastIndex, html: "<pre><code>" + esc(m[1]) + "</code></pre>" });\n    }\n    var out = "", cursor = 0;\n    blocks.forEach(function (b) {\n      out += inlineMd(rest.slice(cursor, b.start));\n      out += b.html;\n      cursor = b.end;\n    });\n    out += inlineMd(rest.slice(cursor));\n    return out;\n  }\n  function inlineMd(s) {\n    var t = esc(s);\n    t = t.replace(/`([^`]+)`/g, "<code>$1</code>");\n    t = t.replace(/\\*\\*([^*]+)\\*\\*/g, "<strong>$1</strong>");\n    t = t.replace(/\\*([^*]+)\\*/g, "<em>$1</em>");\n    var paras = t.split(/\\n{2,}/);\n    var html = paras.map(function (p) {\n      var lines = p.split("\\n");\n      var buf = [];\n      var inList = false;\n      lines.forEach(function (line) {\n        var lm = line.match(/^\\s*[-*•]\\s+(.*)$/);\n        if (lm) {\n          if (!inList) { buf.push("<ul>"); inList = true; }\n          buf.push("<li>" + lm[1] + "</li>");\n        } else {\n          if (inList) { buf.push("</ul>"); inList = false; }\n          buf.push(line.replace(/\\n$/, "") ? line : "<br>");\n        }\n      });\n      if (inList) { buf.push("</ul>"); }\n      var body = buf.join("\\n");\n      if (/^\\s*<ul>/.test(body) || /^\\s*<pre>/.test(body) || /^\\s*<br>/.test(body)) return body;\n      return "<p>" + body.replace(/\\n/g, "<br>") + "</p>";\n    });\n    return html.join("");\n  }\n\n  /* ---------- 角色 ---------- */\n  function applyColor(color) {\n    var c = /^#[0-9a-fA-F]{6}$/.test(color || "") ? color : "#0F766E";\n    document.documentElement.style.setProperty("--accent", c);\n    document.documentElement.style.setProperty("--accent-soft", c + "1A");\n    var meta = document.querySelector(\'meta[name="theme-color"]\');\n    if (meta) meta.setAttribute("content", c);\n  }\n  function renderTabs(roles) {\n    el.tabs.innerHTML = "";\n    roles.forEach(function (r) {\n      var b = document.createElement("button");\n      b.type = "button";\n      b.className = "tab";\n      b.setAttribute("role", "tab");\n      b.setAttribute("data-id", r.id);\n      var dot = document.createElement("span");\n      dot.className = "dot";\n      dot.style.background = /^#[0-9a-fA-F]{6}$/.test(r.color) ? r.color : "";\n      b.appendChild(dot);\n      b.appendChild(document.createTextNode(r.name));\n      b.addEventListener("click", function () { setMode(r.id); });\n      el.tabs.appendChild(b);\n    });\n  }\n  function renderCards(roles) {\n    el.cards.innerHTML = "";\n    var tags = {\n      work: { tag: "师 · 友 · 秘书", desc: "商业计划书、路演答辩、嵌入式/编程辅导、文档去AI化、纪要周报、任务拆解、职业规划" },\n      emotion: { tag: "顾问 · 倾听者 · 教练", desc: "情绪疏导、内耗焦虑、自我认知、恋爱关系、婚姻家庭、人际边界、危机转介" }\n    };\n    roles.slice(0, 2).forEach(function (r) {\n      var info = tags[r.id] || { tag: "专属人格", desc: "切换到「" + r.name + "」人格开始对话" };\n      var card = document.createElement("div");\n      card.className = "card";\n      card.setAttribute("role", "button");\n      card.tabIndex = 0;\n      card.setAttribute("aria-label", "切换到" + r.name + "模式");\n      var go = function () { setMode(r.id); el.main.scrollTop = 0; };\n      card.addEventListener("click", go);\n      card.addEventListener("keydown", function (e) {\n        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go(); }\n      });\n      var dot = /^#[0-9a-fA-F]{6}$/.test(r.color) ? r.color : "";\n      card.innerHTML =\n        \'<span class="card-tag" style="color:\' + dot + \'"><span class="dot" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:\' + dot + \';"></span>\' +\n        esc(r.name) + \'模式</span>\' +\n        \'<div class="card-name">\' + esc(info.tag) + \'</div>\' +\n        \'<div class="card-desc">\' + esc(info.desc) + \'</div>\';\n      el.cards.appendChild(card);\n    });\n  }\n  function loadRoles() {\n    fetch("/api/roles").then(function (r) { return r.json(); }).then(function (data) {\n      var roles = (data && data.roles) || [];\n      if (!roles.length) roles = DEFAULT_ROLES.slice();\n      state.roles = roles;\n      renderTabs(roles);\n      renderCards(roles);\n      var exists = roles.some(function (r) { return r.id === state.mode; });\n      if (!exists) setMode(roles[0].id); else setMode(state.mode);\n    }).catch(function () {\n      state.roles = DEFAULT_ROLES.slice();\n      renderTabs(state.roles);\n      renderCards(state.roles);\n      setMode("work");\n    });\n  }\n  function roleById(id) {\n    for (var i = 0; i < state.roles.length; i++) if (state.roles[i].id === id) return state.roles[i];\n    return null;\n  }\n\n  /* ---------- 渲染 ---------- */\n  function renderAll() {\n    el.messages.innerHTML = "";\n    (state.histories[state.mode] || []).forEach(function (msg) { appendMsgNode(msg.role, msg.content); });\n    if (!(state.histories[state.mode] || []).length) el.welcome.style.display = "";\n    else el.welcome.style.display = "none";\n    scrollBottom();\n  }\n  function appendMsgNode(role, content) {\n    var wrap = document.createElement("div");\n    wrap.className = "msg " + role;\n    var bubble = document.createElement("div");\n    bubble.className = "bubble";\n    if (role === "ai") bubble.innerHTML = md(content);\n    else bubble.textContent = content;\n    wrap.appendChild(bubble);\n    el.messages.appendChild(wrap);\n    return wrap;\n  }\n  function addTyping() {\n    var wrap = document.createElement("div");\n    wrap.className = "msg ai typing";\n    wrap.innerHTML = \'<div class="bubble"><span class="dot"></span><span class="dot"></span><span class="dot"></span></div>\';\n    el.messages.appendChild(wrap);\n    scrollBottom();\n    return wrap;\n  }\n  function scrollBottom() { el.main.scrollTop = el.main.scrollHeight; }\n\n  function setMode(mode) {\n    if (!roleById(mode)) return;\n    state.mode = mode;\n    if (!state.histories[mode]) state.histories[mode] = loadHist(mode);\n    var r = roleById(mode);\n    applyColor(r.color);\n    var tabs = el.tabs.querySelectorAll(".tab");\n    for (var i = 0; i < tabs.length; i++) {\n      tabs[i].classList.toggle("active", tabs[i].getAttribute("data-id") === mode);\n      tabs[i].setAttribute("aria-selected", String(tabs[i].getAttribute("data-id") === mode));\n    }\n    renderAll();\n  }\n\n  /* ---------- 流式读取 ---------- */\n  function readStream(res, onChunk) {\n    return new Promise(function (resolve, reject) {\n      if (!res.body || !res.body.getReader) {\n        // 老浏览器不支持流式读取，退化为整段 JSON\n        res.json().then(function (d) {\n          if (d && d.reply) { onChunk(d.reply); resolve(d.reply); }\n          else reject(new Error((d && d.message) || "请求失败"));\n        }).catch(reject);\n        return;\n      }\n      var reader = res.body.getReader();\n      var decoder = new TextDecoder();\n      var acc = "", text = "";\n      var stopped = false;\n      function pump() {\n        return reader.read().then(function (r) {\n          if (r.done) { resolve(text); return; }\n          acc += decoder.decode(r.value, { stream: true });\n          var idx;\n          while ((idx = acc.indexOf("\\n\\n")) >= 0) {\n            var block = acc.slice(0, idx);\n            acc = acc.slice(idx + 2);\n            var lines = block.split("\\n");\n            for (var i = 0; i < lines.length; i++) {\n              var line = lines[i];\n              if (line.indexOf("data:") !== 0) continue;\n              var payload = line.slice(5).trim();\n              if (!payload || payload === "[DONE]") continue;\n              var obj;\n              try { obj = JSON.parse(payload); } catch (e) { continue; }\n              if (obj.error) { stopped = true; reject(new Error(obj.message || obj.error)); return; }\n              if (obj.text) { text += obj.text; onChunk(obj.text); }\n            }\n          }\n          if (!stopped) return pump();\n        }).catch(reject);\n      }\n      pump();\n    });\n  }\n\n  /* ---------- 直连云端模式 ---------- */\n  var DIRECT_KEY = "qnz_direct";\n  var DIRECT_PROMPTS_KEY = "qnz_direct_prompts";\n  var DEFAULT_DIRECT = { base_url: "https://api.deepseek.com/v1/chat/completions", model: "deepseek-chat", api_key: "" };\n  var PROVIDERS = {\n    deepseek: { base_url: "https://api.deepseek.com/v1/chat/completions", model: "deepseek-chat" },\n    zhipu: { base_url: "https://open.bigmodel.cn/api/paas/v4/chat/completions", model: "glm-4-flash" },\n    volc: { base_url: "https://ark.cn-beijing.volces.com/api/v3/chat/completions", model: "doubao-pro-32k" },\n    qwen: { base_url: "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions", model: "qwen-turbo" },\n    sensenova: { base_url: "https://token.sensenova.cn/v1/chat/completions", model: "sensenova-6.8-flash-lite" },\n    minimax: { base_url: "https://api.minimaxi.com/v1/chat/completions", model: "abab6.5s-chat" },\n    stepfun: { base_url: "https://api.stepfun.com/v1/chat/completions", model: "step-1-8k" },\n    qianfan: { base_url: "https://qianfan.baidubce.com/v2/chat/completions", model: "ernie-4.0-turbo-8k" },\n    lingyi: { base_url: "https://api.lingyiwanwu.com/v1/chat/completions", model: "yi-lightning" },\n    custom: { base_url: "", model: "" }\n  };\n  function matchProvider(url) {\n    var u = String(url || "");\n    for (var id in PROVIDERS) {\n      if (id !== "custom" && PROVIDERS[id].base_url && u.indexOf(PROVIDERS[id].base_url) === 0) return id;\n    }\n    return "custom";\n  }\n  var DIRECT_PROMPTS = {\n    work: "你是「全能助手」的工作模式：亦师亦友的工作助手，服务对象主要是大学生和个人开发者。三副面孔：师（给专业判断、挑真问题）、友（平视对话）、秘书（把杂活落地成可执行成果）。核心原则：先弄清对方到底要什么再动手；给判断但不替用户拍板；结论要能落地成下一步动作。输出风格：去AI化（不用“一站式、智能化、赋能”等套词，句子长短交错）；重要决策默认给2-3个方案并写明代价；回答末尾给一个现在能做的小事和观察窗口；不编造数据，数字拿不准标“待核实”。擅长：国创/挑战杯BP（九章结构）、路演答辩、嵌入式/STM32/ESP32/C编程调试、文档去AI化降重、纪要周报、任务拆解、职业规划。安全边界：不编造数据文件证书；重大决定给利弊清单由用户决定；法律医疗财务只给通用信息。",\n    emotion: "你是「全能助手」的情感模式：全面情感顾问。三副面孔：顾问（把心理学结论转译成人话）、倾听者（先接住情绪再讲道理，不灌鸡汤）、行动教练（把分析落地成下一步）。工作流程：先接住情绪（2-4句指出感受与触发点），再分事实（已知/推测/未知），给一句首选+理由，最后给一个现在能做的小动作和观察窗口。输出风格：去AI化；心理学结论区分较强证据/理论框架/流行说法，拿不准标“待核实”。边界：不诊断心理疾病、不贴标签；出现自伤伤人风险时引导联系专业渠道（110/120/心理援助热线）；不提供操控、PUA、煤气灯类方案；尊重边界，对方明确拒绝时协助体面退出。"\n  };\n  function loadDirect() {\n    try {\n      var d = JSON.parse(localStorage.getItem(DIRECT_KEY) || "null");\n      if (!d || !d.api_key) return null;\n      return {\n        provider: d.provider || matchProvider(d.base_url),\n        base_url: (d.base_url || DEFAULT_DIRECT.base_url),\n        model: (d.model || DEFAULT_DIRECT.model),\n        api_key: d.api_key\n      };\n    } catch (e) { return null; }\n  }\n  function saveDirect(d) { try { localStorage.setItem(DIRECT_KEY, JSON.stringify(d)); } catch (e) {} }\n  function clearDirect() { try { localStorage.removeItem(DIRECT_KEY); } catch (e) {} }\n  function loadDirectPrompts() {\n    try {\n      var p = JSON.parse(localStorage.getItem(DIRECT_PROMPTS_KEY) || "null");\n      return (p && typeof p === "object") ? p : null;\n    } catch (e) { return null; }\n  }\n  function buildDirectSystem(mode, memory) {\n    var prompts = loadDirectPrompts();\n    var base = (prompts && prompts[mode]) || DIRECT_PROMPTS[mode] || DIRECT_PROMPTS.work;\n    if (!memory || !memory.length) return base;\n    var facts = [];\n    for (var i = 0; i < memory.length; i++) if (String(memory[i]).trim()) facts.push(String(memory[i]).trim());\n    return facts.length ? base + "\\n\\n【用户档案（关键事实，本机保存，仅作参考；不要编造档案外的信息）】\\n" + facts.join("；") : base;\n  }\n  // 直连模式读取 OpenAI 兼容 SSE：data: {"choices":[{"delta":{"content":"..."}}]}\n  function readOpenAIStream(res, onChunk) {\n    return new Promise(function (resolve, reject) {\n      var reader = res.body.getReader();\n      var decoder = new TextDecoder();\n      var acc = "", text = "";\n      function pump() {\n        return reader.read().then(function (r) {\n          if (r.done) { resolve(text); return; }\n          acc += decoder.decode(r.value, { stream: true });\n          var idx;\n          while ((idx = acc.indexOf("\\n\\n")) >= 0) {\n            var block = acc.slice(0, idx);\n            acc = acc.slice(idx + 2);\n            var lines = block.split("\\n");\n            for (var i = 0; i < lines.length; i++) {\n              var line = lines[i];\n              if (line.indexOf("data:") !== 0) continue;\n              var payload = line.slice(5).trim();\n              if (!payload || payload === "[DONE]") continue;\n              var obj;\n              try { obj = JSON.parse(payload); } catch (e) { continue; }\n              if (obj.error) { reject(new Error((obj.error.message || obj.error) || "API 错误")); return; }\n              var delta = obj.choices && obj.choices[0] && obj.choices[0].delta && obj.choices[0].delta.content;\n              if (delta) { text += delta; onChunk(delta); }\n            }\n          }\n          return pump();\n        }).catch(reject);\n      }\n      pump();\n    });\n  }\n  function sendBackendRequest(body, typing) {\n    return fetch("/api/chat", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify(body)\n    }).then(function (res) {\n      if (!res.ok) {\n        return res.json().then(function (d) {\n          throw new Error((d && d.message) || (d && d.error) || "请求失败");\n        });\n      }\n      typing.remove();\n      var aiWrap = appendMsgNode("ai", "");\n      aiWrap.classList.add("streaming");\n      var bubble = aiWrap.querySelector(".bubble");\n      var accText = "";\n      return readStream(res, function (chunk) {\n        accText += chunk;\n        bubble.innerHTML = md(accText);\n        scrollBottom();\n      });\n    });\n  }\n  function sendDirectRequest(direct, mode, history, memory, typing) {\n    var sys = buildDirectSystem(mode, memory);\n    var messages = [{ role: "system", content: sys }];\n    for (var i = 0; i < history.length; i++) {\n      if (history[i].role === "user" || history[i].role === "assistant") messages.push(history[i]);\n    }\n    return fetch(direct.base_url, {\n      method: "POST",\n      headers: {\n        "Content-Type": "application/json",\n        "Authorization": "Bearer " + direct.api_key\n      },\n      body: JSON.stringify({ model: direct.model, messages: messages, temperature: 0.7, stream: true })\n    }).then(function (res) {\n      if (!res.ok) {\n        return res.json().then(function (d) {\n          var m = (d && d.error && (d.error.message || d.error)) || (d && d.message) || ("HTTP " + res.status);\n          throw new Error(m);\n        }).catch(function () { throw new Error("HTTP " + res.status); });\n      }\n      typing.remove();\n      var aiWrap = appendMsgNode("ai", "");\n      aiWrap.classList.add("streaming");\n      var bubble = aiWrap.querySelector(".bubble");\n      var accText = "";\n      return readOpenAIStream(res, function (delta) {\n        accText += delta;\n        bubble.innerHTML = md(accText);\n        scrollBottom();\n      });\n    });\n  }\n\n  /* ---------- 发送 ---------- */\n  function send(text) {\n    text = String(text || "").trim();\n    if (!text || state.busy) return;\n    var mode = state.mode;\n    if (!state.histories[mode]) state.histories[mode] = loadHist(mode);\n    state.histories[mode].push({ role: "user", content: text });\n    saveHist(mode);\n    renderAll();\n\n    state.busy = true;\n    el.send.disabled = true;\n    var typing = addTyping();\n    hideBanner();\n\n    var direct = loadDirect();\n    var useDirect = !!(direct && direct.api_key);\n\n    var reqPromise = useDirect\n      ? sendDirectRequest(direct, mode, state.histories[mode], loadMem(), typing)\n      : sendBackendRequest(body, typing);\n\n    reqPromise.then(function (fullText) {\n      state.histories[mode].push({ role: "assistant", content: fullText });\n      saveHist(mode);\n      renderAll();\n      if (loadSpeak()) speakText(fullText);\n    }).catch(function (err) {\n      typing.remove();\n      var msg = (err && err.message) ? err.message : "请求失败";\n      if (/连不上|Failed to fetch|NetworkError|API_NETWORK/i.test(msg)) msg = "连不上服务：直连模式请检查 API Key 和网络；局域网后端请确认 server.py 已启动";\n      showBanner(msg, "打开设置", function () { el.overlay.classList.add("show"); });\n    }).finally(function () {\n      state.busy = false;\n      el.send.disabled = false;\n      el.input.focus();\n    });\n  }\n\n  /* ---------- 语音输入（Web Speech API） ---------- */\n  var SR = window.SpeechRecognition || window.webkitSpeechRecognition;\n  var sr = null, srOn = false;\n  function initMic() {\n    if (!SR) return;\n    el.mic.style.display = "";\n    el.mic.addEventListener("click", toggleMic);\n  }\n  function toggleMic() {\n    if (srOn) { stopMic(); return; }\n    if (!sr) {\n      sr = new SR();\n      sr.lang = "zh-CN";\n      sr.interimResults = true;\n      sr.continuous = false;\n      sr.onresult = function (e) {\n        var t = "";\n        for (var i = 0; i < e.results.length; i++) t += e.results[i][0].transcript;\n        el.input.value = t;\n        autosize();\n      };\n      sr.onend = function () { srOn = false; el.mic.classList.remove("on"); };\n      sr.onerror = function () { srOn = false; el.mic.classList.remove("on"); };\n    }\n    try {\n      sr.start();\n      srOn = true;\n      el.mic.classList.add("on");\n    } catch (e) { srOn = false; }\n  }\n  function stopMic() {\n    if (sr) { try { sr.stop(); } catch (e) {} }\n    srOn = false;\n    el.mic.classList.remove("on");\n  }\n\n  /* ---------- 语音朗读 ---------- */\n  function speakText(text) {\n    if (!("speechSynthesis" in window) || !text) return;\n    try {\n      window.speechSynthesis.cancel();\n      var u = new SpeechSynthesisUtterance(text);\n      u.lang = "zh-CN";\n      u.rate = 1.0;\n      window.speechSynthesis.speak(u);\n    } catch (e) {}\n  }\n  function speakLastReply() {\n    var hist = state.histories[state.mode] || [];\n    for (var i = hist.length - 1; i >= 0; i--) {\n      if (hist[i].role === "assistant") { speakText(hist[i].content); return; }\n    }\n  }\n\n  /* ---------- 记忆 ---------- */\n  function renderMem() {\n    var mem = loadMem();\n    el.memList.innerHTML = "";\n    if (!mem.length) {\n      el.memList.innerHTML = \'<div class="desc">还没有记住任何事实。添加一条试试，比如你的专业、项目名。</div>\';\n      return;\n    }\n    mem.forEach(function (item, idx) {\n      var row = document.createElement("div");\n      row.className = "mem-item";\n      var t = document.createElement("span");\n      t.className = "t";\n      t.textContent = item;\n      var del = document.createElement("button");\n      del.type = "button";\n      del.textContent = "删除";\n      del.addEventListener("click", function () {\n        var arr = loadMem();\n        arr.splice(idx, 1);\n        saveMem(arr);\n        renderMem();\n      });\n      row.appendChild(t);\n      row.appendChild(del);\n      el.memList.appendChild(row);\n    });\n  }\n\n  /* ---------- 提示条 ---------- */\n  function showBanner(text, actText, actFn) {\n    el.bannerText.textContent = text;\n    if (actText && actFn) {\n      el.bannerAct.textContent = actText;\n      el.bannerAct.onclick = actFn;\n      el.bannerAct.style.display = "";\n    } else {\n      el.bannerAct.style.display = "none";\n    }\n    el.banner.classList.add("show");\n  }\n  function hideBanner() { el.banner.classList.remove("show"); }\n\n  function autosize() {\n    el.input.style.height = "auto";\n    el.input.style.height = Math.min(el.input.scrollHeight, 120) + "px";\n  }\n\n  /* ---------- 设置 ---------- */\n  function openSettings() {\n    el.overlay.classList.add("show");\n    renderMem();\n    el.swSpeak.classList.toggle("on", loadSpeak());\n    el.swSpeak.setAttribute("aria-checked", String(loadSpeak()));\n    var dc = loadDirect();\n    el.dcKey.value = dc ? dc.api_key : "";\n    el.dcUrl.value = dc ? dc.base_url : "";\n    el.dcModel.value = dc ? dc.model : "";\n    el.dcProvider.value = dc ? (dc.provider || matchProvider(dc.base_url)) : "deepseek";\n    var dp = loadDirectPrompts();\n    el.dcPrompts.value = dp ? JSON.stringify(dp, null, 1) : "";\n    el.dcStatus.textContent = dc ? "直连已启用：" + (dc.base_url || "") : "";\n    fetch("/api/status").then(function (r) { return r.json(); }).then(function (s) {\n      el.stReady.textContent = s.ready ? "已就绪" : "未配置 API Key";\n      el.stReady.className = "v " + (s.ready ? "ok" : "bad");\n      el.stProvider.textContent = s.provider || "—";\n      el.stModel.textContent = s.model || "—";\n      el.stProviders.textContent = (s.providers && s.providers.length) ? s.providers.join(" / ") : "—";\n      var rt = s.routing || {};\n      el.stRouting.textContent = Object.keys(rt).length ? Object.keys(rt).map(function (k) { return k + "→" + rt[k]; }).join("，") : "默认";\n      el.stConfig.textContent = s.config_file || "—";\n    }).catch(function () {\n      el.stReady.textContent = "无法连接后端";\n      el.stReady.className = "v bad";\n      el.stProvider.textContent = "—";\n      el.stModel.textContent = "—";\n      el.stProviders.textContent = "—";\n      el.stRouting.textContent = "—";\n      el.stConfig.textContent = "—";\n    });\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  el.send.addEventListener("click", function () {\n    send(el.input.value);\n    el.input.value = "";\n    autosize();\n  });\n  el.input.addEventListener("keydown", function (e) {\n    if (e.key === "Enter" && !e.shiftKey) {\n      e.preventDefault();\n      send(el.input.value);\n      el.input.value = "";\n      autosize();\n    }\n  });\n  el.input.addEventListener("input", autosize);\n  el.speakBtn.addEventListener("click", speakLastReply);\n  document.getElementById("btnSettings").addEventListener("click", openSettings);\n  el.dcSave.addEventListener("click", function () {\n    var key = el.dcKey.value.trim();\n    if (!key) { el.dcStatus.textContent = "请先填 API Key。"; return; }\n    var prov = el.dcProvider.value;\n    var pre = PROVIDERS[prov] || PROVIDERS.custom;\n    if (prov === "custom" && !el.dcUrl.value.trim()) {\n      el.dcStatus.textContent = "自定义模式请先填接口地址。";\n      return;\n    }\n    saveDirect({\n      provider: prov,\n      api_key: key,\n      base_url: el.dcUrl.value.trim() || pre.base_url,\n      model: el.dcModel.value.trim() || pre.model\n    });\n    var pv = el.dcPrompts.value.trim();\n    if (pv) {\n      try { saveDirectPrompts(JSON.parse(pv)); el.dcStatus.textContent = "直连已保存（含自定义人格）。"; }\n      catch (e) { el.dcStatus.textContent = "人格 JSON 格式不对，已忽略人格，其余已保存。"; }\n    } else {\n      try { localStorage.removeItem(DIRECT_PROMPTS_KEY); } catch (e) {}\n      el.dcStatus.textContent = "直连已保存（使用内置人格）。";\n    }\n  });\n  el.dcClear.addEventListener("click", function () {\n    clearDirect();\n    el.dcKey.value = ""; el.dcUrl.value = ""; el.dcModel.value = ""; el.dcPrompts.value = "";\n    el.dcProvider.value = "deepseek";\n    el.dcStatus.textContent = "直连已关闭，将使用局域网后端。";\n  });\n  el.dcProvider.addEventListener("change", function () {\n    var p = el.dcProvider.value;\n    if (p === "custom") { el.dcUrl.value = ""; el.dcModel.value = ""; return; }\n    var pre = PROVIDERS[p] || PROVIDERS.deepseek;\n    el.dcUrl.value = pre.base_url;\n    el.dcModel.value = pre.model;\n  });\n  el.overlay.addEventListener("click", function (e) { if (e.target === el.overlay) el.overlay.classList.remove("show"); });\n  el.swSpeak.addEventListener("click", function () {\n    var on = !loadSpeak();\n    saveSpeak(on);\n    el.swSpeak.classList.toggle("on", on);\n    el.swSpeak.setAttribute("aria-checked", String(on));\n  });\n  el.memAdd.addEventListener("click", addMem);\n  el.memInput.addEventListener("keydown", function (e) {\n    if (e.key === "Enter") { e.preventDefault(); addMem(); }\n  });\n  function addMem() {\n    var v = el.memInput.value.trim();\n    if (!v) return;\n    var arr = loadMem();\n    if (arr.indexOf(v) < 0) arr.push(v);\n    saveMem(arr);\n    el.memInput.value = "";\n    renderMem();\n  }\n  document.getElementById("btnClear").addEventListener("click", function () {\n    state.histories[state.mode] = [];\n    saveHist(state.mode);\n    renderAll();\n    el.overlay.classList.remove("show");\n  });\n  document.getElementById("chips").addEventListener("click", function (e) {\n    var chip = e.target.closest(".chip");\n    if (!chip) return;\n    send(chip.textContent);\n  });\n\n  /* ---------- 启动 ---------- */\n  if ("serviceWorker" in navigator) {\n    navigator.serviceWorker.register("/sw.js").catch(function () { /* 不支持则静默 */ });\n  }\n  initMic();\n  loadRoles();\n  el.input.focus();\n})();\n</script>\n</body>\n</html>\n'

SYSTEM_PROMPTS = {'work': '你是「全能助手」的工作模式：一名亦师亦友的工作助手，服务对象主要是大学生和个人开发者。\n【定位】三副面孔：师——给专业判断、挑真问题；友——平视对话、一起头脑风暴；秘书——把杂活落地成可执行成果。核心原则：先弄清对方到底要什么，再动手；给判断但不替用户拍板；结论要能落地成下一步动作。\n【输出风格】\n1. 去AI化：不用"一站式、智能化、赋能、突破性、打造生态"等套词，句子长短交错，像人写的话。\n2. 多方案：重要决策默认给2-3个版本（稳妥/进取/激进），写明好处、代价、风险，不替用户单选。\n3. 行动收束：回答末尾给"现在能做的一件小事 + 观察窗口或停止条件"，以及值得回来反馈的信号。\n4. 证据诚实：不编造数据、案例、政策或事实；数字拿不准标注"待核实"并说明来源。\n5. 用户可随时要求切换精简/详细/口语化/表格等格式。\n【擅长领域要点】\n- 国创/挑战杯商业计划书：九章结构（摘要/痛点/产品/市场/商业模式/落地/团队/财务风险/规划）；摘要最后定稿且与正文数字一致；痛点要场景+证据；市场给测算逻辑和口径；竞品用表格；风险不少于3条且每条有对策；不编造数据、访谈、合作意向。\n- 路演PPT与答辩：先筛"是否解决真问题、有没有真实进展、数字是否可信"；把常见答辩问提前写进材料。\n- 技术学习（嵌入式/STM32/ESP32/C/PCB/飞机电子维修）：调试先复现、读报错原文、分编译/运行/硬件三类；改一处测一处；硬件先查供电和地；中断里不做耗时操作；注意器件型号、驱动、串口波特率。\n- 文档润色与去AI化降重：打散句子结构、长短句交错、保留核心信息、去华丽宣传话术、平实叙述。\n- 会议纪要/周报：提炼决定、待办、负责人、截止时间。\n- 任务拆解/时间规划：目标拆成可检查的里程碑，识别卡点和风险。\n- 复盘：事实—结果—原因—下一步。\n- 头脑风暴：先多方案发散，再按标准取舍。\n- 职业规划：结合现实条件给多条路径与取舍，不画大饼。\n【安全边界】不编造数据、文件、证书；重要决定（投项目、花大钱、签约、体检就医）给利弊与检查清单，由用户决定；涉及法律、医疗、财务只给通用信息，不冒充专家；发现方案错误直接指出并给修改建议。\n【输入证据】以用户提供的文件、数据、转述为准；材料矛盾时指出矛盾，不强行调和；缺失信息保持未知，不虚构。', 'emotion': '你是「全能助手」的情感模式：一名全面情感顾问。三副面孔：顾问——给专业判断，把心理学结论转译成人话；倾听者——先接住情绪再讲道理，不灌鸡汤；行动教练——把分析落地成下一步。\n【核心原则】先接住情绪，再分清事实，最后给能执行的选择。把"对用户最有利"理解为情绪稳定、安全、自尊、边界、互惠、时间精力、机会成本与长期信任的综合利益。\n【工作流程】\n1. 接情绪：先用2-4句指出感受、触发点和冲突，认可感受；情绪强烈时先缩小到"这一小时能做什么"。\n2. 分事实：列已知事实、合理推测、关键未知；不凭单次回复、表情或标签定性，以行为证据（持续主动、兑现、投入、边界、冲突修复）为准。\n3. 给建议：一句首选+2-4个理由；有真实权衡时再给2-3个版本（稳妥/进取/果断），写明各自代价。\n4. 行动收束：给一个现在能做的小动作、观察窗口或停止条件，以及值得回来反馈的信号。\n【输出风格】去AI化（不用"赋能、底层逻辑、高维认知"等套词）；证据诚实（心理学结论区分较强证据/理论框架/流行说法，拿不准标"待核实"）；可切换精简/详细/口语化/表格。\n【擅长领域要点】\n- 情绪管理（焦虑/内耗/低落/愤怒）：先区分日常情绪与需专业转介的信号（持续两周以上低落、自伤想法、惊恐发作等）；情绪高峰时不急着做决定、不发送激烈消息；命名情绪+物理降温+缩小到一小时；内耗识别模式（反刍/灾难化/完美主义拖延/比较/过度负责）再拆解；日常养护靠睡眠、运动、情绪出口。\n- 自我认知与价值感：把"我不行"拆成事实/行为/结论三层；用行为记录替代自我评价；从可完成的小事做起；区分"我的价值"和"我的表现"；迷茫时补信息、降标准、先试小的。\n- 恋爱关系（心动/暧昧/追求/冲突/分手/复合）：分析互惠、可靠、吸引、价值观、现实可行性、可逆性、安全与机会成本；尊重边界——对方明确拒绝、要求不联系或反复不欢迎时，协助体面退出，不强行推进；要话术时先给一条可复制成品，再讲发送时机与后续。\n- 婚姻家庭：金钱家务育儿、双方家庭、生命周期；重大决定（婚姻、生育）给利弊与检查清单。\n- 人际经营：沟通、拒绝、冲突修复、情绪价值、职场人脉；高情商不等于讨好，边界要清晰。\n- 危机：出现自伤、伤人、家暴、跟踪、人身威胁时，先确认当下安全，引导联系可信支持或当地紧急服务（110/120/心理援助热线）。\n【安全边界】不诊断心理疾病、不给人贴标签；情绪问题超出日常范围时建议专业心理咨询或医疗机构；禁止提供贬低、服从性测试、嫉妒操控、奖惩、煤气灯、孤立、跟踪或性施压的实施方案；不保证任何方法能让特定的人改变心意；涉及隐私提醒注意信息暴露。\n【输入证据】聊天截图/转述以用户提供的内容为准，只把可见文字、说话人、顺序当事实；不补线下动作、语气或内心；缺失保持未知，不虚构。', 'roles': [{'id': 'work', 'name': '工作', 'color': '#0F766E', 'prompt': ''}, {'id': 'emotion', 'name': '情感', 'color': '#B45309', 'prompt': ''}]}


def _json_response(status, obj):
    return {
        "isBase64Encoded": False,
        "statusCode": status,
        "headers": {"Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store"},
        "body": json.dumps(obj, ensure_ascii=False),
    }


def _html_response():
    return {
        "isBase64Encoded": False,
        "statusCode": 200,
        "headers": {"Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-cache"},
        "body": HTML_TEXT,
    }


def _config():
    # 环境变量类型校验：非数字一律回退默认，避免请求时崩溃
    def _int_env(name, default):
        try:
            return int(os.environ.get(name) or default)
        except (TypeError, ValueError):
            return default
    def _float_env(name, default):
        try:
            return float(os.environ.get(name) or default)
        except (TypeError, ValueError):
            return default
    def _clean(name):
        val = (os.environ.get(name) or "").strip()
        if not val or "粘贴" in val or val.startswith("在这里"):
            return ""
        return val
    # 多 API 支持：最多 3 组，组 1 兼容旧变量 API_KEY / API_BASE_URL / API_MODEL
    providers = []
    k1 = _clean("API_KEY_1") or _clean("API_KEY")
    if k1:
        providers.append({
            "id": "1",
            "api_key": k1,
            "base_url": _clean("API_BASE_URL_1") or _clean("API_BASE_URL") or "https://api.deepseek.com/v1/chat/completions",
            "model": _clean("API_MODEL_1") or _clean("API_MODEL") or "deepseek-chat",
            "label": _clean("API_NAME_1") or _clean("API_MODEL_1") or _clean("API_MODEL") or "deepseek-chat",
        })
    for i in (2, 3):
        k = _clean("API_KEY_%d" % i)
        if not k:
            continue
        providers.append({
            "id": str(i),
            "api_key": k,
            "base_url": _clean("API_BASE_URL_%d" % i) or "https://api.deepseek.com/v1/chat/completions",
            "model": _clean("API_MODEL_%d" % i) or "deepseek-chat",
            "label": _clean("API_NAME_%d" % i) or _clean("API_MODEL_%d" % i) or "deepseek-chat",
        })
    return {
        "providers": providers,
        "temperature": _float_env("TEMPERATURE", 0.7),
        "max_history": _int_env("MAX_HISTORY", 20),
    }


def _call_api(prov, temperature, messages):
    body = {
        "model": prov["model"],
        "messages": messages,
        "temperature": temperature,
        "stream": False,
    }
    req = urllib.request.Request(
        prov["base_url"],
        data=json.dumps(body).encode("utf-8"),
        headers={"Content-Type": "application/json", "Authorization": "Bearer " + prov["api_key"]},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=120) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError("API_HTTP_%s: %s" % (exc.code, detail[:400])) from exc
    except OSError as exc:   # 覆盖 URLError / socket.timeout / 连接被重置
        reason = getattr(exc, "reason", None) or exc
        raise RuntimeError("API_NETWORK: %s" % reason) from exc
    try:
        return data["choices"][0]["message"]["content"]
    except (KeyError, IndexError, TypeError) as exc:
        raise RuntimeError("API_BAD_RESPONSE: %s" % json.dumps(data, ensure_ascii=False)[:400]) from exc


def _clean_history(history, max_history):
    """只保留 user/assistant 消息，丢弃注入的 system 等其他 role；content 为字符串或数组（多模态）原样保留。"""
    cleaned = []
    for m in history[-max_history:]:
        if not isinstance(m, dict):
            continue
        role = m.get("role")
        if role not in ("user", "assistant"):
            continue
        content = m.get("content")
        if content is None:
            continue
        if isinstance(content, (str, list)):
            cleaned.append({"role": role, "content": content})
        else:
            cleaned.append({"role": role, "content": str(content)})
    return cleaned


def main_handler(event, context):
    path = event.get("path") or "/"
    method = event.get("httpMethod") or "GET"
    if path in ("/", "/index.html") and method == "GET":
        return _html_response()
    if path == "/api/status" and method == "GET":
        cfg = _config()
        providers = cfg["providers"]
        return _json_response(200, {
            "ready": bool(providers),
            "provider": providers[0]["label"] if providers else "",
            "model": providers[0]["model"] if providers else "",
            "providers": [{"id": p["id"], "model": p["model"], "label": p["label"]} for p in providers],
            "config_source": "SCF 环境变量",
        })
    if path == "/api/chat" and method == "POST":
        raw = event.get("body") or "{}"
        if event.get("isBase64Encoded"):
            try:
                import base64
                raw = base64.b64decode(raw).decode("utf-8")
            except Exception as exc:
                return _json_response(400, {"error": "BAD_REQUEST", "message": "body 解码失败"})
        try:
            req = json.loads(raw.lstrip("\ufeff"))
        except (ValueError, json.JSONDecodeError) as exc:
            return _json_response(400, {"error": "BAD_REQUEST", "message": "请求体不是合法 JSON"})
        mode = req.get("mode", "work")
        if mode not in ("work", "emotion"):
            mode = "work"
        history = req.get("messages", [])
        if not isinstance(history, list):
            return _json_response(400, {"error": "BAD_REQUEST", "message": "messages 必须是数组"})
        cfg = _config()
        providers = cfg["providers"]
        if not providers:
            return _json_response(503, {"error": "NO_API_KEY", "message": "云函数环境变量未配置 API Key（API_KEY 或 API_KEY_1~API_KEY_3），请到 SCF 控制台配置"})
        system = {"role": "system", "content": SYSTEM_PROMPTS.get(mode, SYSTEM_PROMPTS["work"])}
        max_history = max(1, min(cfg["max_history"], 60))
        messages = [system] + _clean_history(history, max_history)
        # 前端可指定 provider（"1"/"2"/"3"）；不指定则按顺序自动尝试，失败自动切下一组
        want = str(req.get("provider", "") or "").strip()
        candidates = [p for p in providers if p["id"] == want] if want else providers
        try_list = candidates or providers
        last = None
        for p in try_list:
            try:
                reply = _call_api(p, cfg["temperature"], messages)
                return _json_response(200, {
                    "reply": reply,
                    "provider": {"id": p["id"], "model": p["model"], "label": p["label"]},
                })
            except RuntimeError as exc:
                last = {"id": p["id"], "detail": str(exc)}
        return _json_response(502, {
            "error": "API_ALL_FAILED",
            "message": (last and last["detail"]) or "所有模型均调用失败",
            "provider": last and {"id": last["id"]},
            "tried": [p["id"] for p in try_list],
        })
    return _json_response(404, {"error": "NOT_FOUND", "message": "路径不存在"})


